#![allow(long_running_const_eval)]
// generated by p5_allow_the_guard.py : width=6 policy=sat
const W: i32 = 6;
const LO: i32 = -(1i32 << (W - 1));
const HI: i32 = (1i32 << (W - 1)) - 1;
const N: i64 = (HI as i64) - (LO as i64) + 1;

const fn op(a: i64, b: i64) -> i64 {
    if false {
        let mut r = (a + b - LO as i64) % N;
        if r < 0 {
            r += N;
        }
        r + LO as i64
    } else {
        let s = a + b;
        if s > HI as i64 {
            HI as i64
        } else if s < LO as i64 {
            LO as i64
        } else {
            s
        }
    }
}

const fn violations() -> u64 {
    let mut bad: u64 = 0;
    let mut a = LO as i64;
    while a <= HI as i64 {
        let mut b = LO as i64;
        while b <= HI as i64 {
            let mut c = LO as i64;
            while c <= HI as i64 {
                if op(op(a, b), c) != op(a, op(b, c)) {
                    bad += 1;
                }
                c += 1;
            }
            b += 1;
        }
        a += 1;
    }
    bad
}

const COUNT: u64 = violations();
fn main() {
    println!("W={} policy=sat violations={}", W, COUNT);
}
